do $$
declare v_provider uuid:='9cc8ef21-52ec-4c18-849a-598ba1072459';v_country uuid;v_cp uuid;v_trial uuid;v_course uuid;r record;begin select id into v_country from ref.countries where iso_alpha2='AU';select id into v_cp from pipeline.layer2_country_completeness_profiles where country_id=v_country and active=true order by created_at desc limit 1;insert into pipeline.layer2_completeness_trials(country_id,completeness_profile_id,provider_id,trial_mode,requested_batch_size,status,baseline_summary,result_summary,recommendation,change_control_ref,uat_ref,started_at) values(v_country,v_cp,v_provider,'adaptive_provider_batch',5,'running',jsonb_build_object('batch_size',5,'provider','Federation University Australia','cohort',2,'purpose','second validation cohort after first cohort canonical completeness improved 37.5 to 80.0'),'{}','{}','CF-CHG-20260823-029','M2.1-FEDERATION-TRIAL-C2-2026-08-24',now()) returning id into v_trial;for r in select * from (values (1,'062139A','https://www.federation.edu.au/courses/dsb5-bachelor-of-biomedical-science/','health/science current-page validation'),(2,'0100646','https://www.federation.edu.au/courses/dhk5-bachelor-of-criminology-and-criminal-justice/','social science current-page validation'),(3,'085212G','https://www.federation.edu.au/courses/dhc5-bachelor-of-community-and-human-services/','community services current-page validation'),(4,'089465J','https://www.federation.edu.au/courses/dtz5-bachelor-of-education-primary/','education current-page validation'),(5,'115403C','https://www.federation.edu.au/courses/dpy5-bachelor-of-physiotherapy/','allied health current-page validation')) x(rank,code,url,reason) loop select id into v_course from catalogue.courses where provider_id=v_provider and course_code=r.code limit 1;insert into pipeline.layer2_completeness_trial_courses(trial_id,course_id,provider_id,sample_rank,selection_reason,baseline_factual,baseline_context,status) values(v_trial,v_course,v_provider,r.rank,r.reason||' | target='||r.url,pipeline.layer2_course_factual_snapshot(v_course),'{}','selected');end loop;end $$;
